// Lấy object dữ liệu từ msg.payload (nếu payload là chuỗi JSON thì tự động parse)
const input = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;

const result = [];

// Duyệt qua tất cả các key trong object đầu vào
for (const [key, value] of Object.entries(input)) {
    // Bỏ qua trường "time" chỉ lấy các giá trị tag
    if (key !== 'time' && value !== null && value !== undefined) {
        result.push({
            tag: `danh_dong:${key}`,
            value: Number(value)
        });
    }
}

// Chuyển đổi timestamp ISO từ trường "time" sang dạng epoch seconds (hoặc dùng thời gian hiện tại nếu không có time)
let timestampSeconds;
if (input.time) {
    timestampSeconds = Math.floor(new Date(input.time).getTime() / 1000).toString();
} else {
    timestampSeconds = Math.floor(Date.now() / 1000).toString();
}

// Gán kết quả vào msg.payload
msg.payload = {
    d: result,
    ts: timestampSeconds
};

return msg;

const input = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;

const result = [];

// Các key giữ nguyên prefix (không thêm mu_tap:)
const keepOriginalTagKeys = ['robot:counter', 'r_active_energy'];

for (const [key, value] of Object.entries(input)) {
    if (key !== 'time' && value !== null && value !== undefined) {
        // Xác định prefix dựa trên key
        const tag = keepOriginalTagKeys.includes(key) ? key : `mu_tap:${key}`;

        result.push({
            tag: tag,
            value: Number(value)
        });
    }
}

// Chuyển đổi timestamp ISO sang epoch seconds (dạng chuỗi)
let timestampSeconds;
if (input.time) {
    timestampSeconds = Math.floor(new Date(input.time).getTime() / 1000).toString();
} else {
    timestampSeconds = Math.floor(Date.now() / 1000).toString();
}

msg.payload = {
    d: result,
    ts: timestampSeconds
};

return msg;
